// setup body — receives ctx. App-layer plugins install SUSPENDED;
// the user enables them manually. overrides.appName renames #brandBtn.
var btn = document.createElement('button');
btn.className = 'btn my-app-btn';
btn.textContent = 'Action';
btn.onclick = function () {
  ctx.api.data.createCard({ title: 'From My App', body: '', tags: ['my-app'] });
  ctx.api.ui.showToast('Created a card', 'success');
};
ctx.api.ui.inject('.header', btn, 'append');

ctx.logger.info('my-app ready');
